{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: ov [FILE]")
		return
	}

	fileName := os.Args[1]
	if fileName == "--help" || fileName == "-h" {
		printHelp()
		return
	}

	file, err := os.Open(fileName)
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	var lines []string
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}

	if err := scanner.Err(); err != nil {
		fmt.Printf("Error reading file: %v\n", err)
		return
	}

	runPager(lines, fileName)
}

func printHelp() {
	fmt.Println("ov is a feature rich pager(such as more/less).")
	fmt.Println("Usage: ov [flags] [FILE]...")
	// ... add more help output if needed
}

func runPager(lines []string, fileName string) {
	state, err := getSttyState()
	if err != nil {
		fmt.Printf("Error getting stty state: %v\n", err)
		return
	}
	defer restoreSttyState(state)

	setRawMode()

	offset := 0
	for {
		rows, cols := getTermSize()
		drawScreen(lines, offset, rows, cols, fileName)

		key := readKey()
		if key == "q" {
			break
		} else if key == "j" || key == "\x1b[B" { // Down
			if offset < len(lines)-rows+1 {
				offset++
			}
		} else if key == "k" || key == "\x1b[A" { // Up
			if offset > 0 {
				offset--
			}
		} else if key == " " || key == "\x1b[6~" { // Page Down
			offset += rows - 1
			if offset > len(lines)-rows+1 {
				offset = len(lines) - rows + 1
				if offset < 0 {
					offset = 0
				}
			}
		} else if key == "b" || key == "\x1b[5~" { // Page Up
			offset -= rows - 1
			if offset < 0 {
				offset = 0
			}
		}
	}
}

func getSttyState() (string, error) {
	cmd := exec.Command("stty", "-g")
	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	return strings.TrimSpace(string(out)), err
}

func restoreSttyState(state string) {
	cmd := exec.Command("stty", state)
	cmd.Stdin = os.Stdin
	cmd.Run()
}

func setRawMode() {
	cmd := exec.Command("stty", "raw", "-echo")
	cmd.Stdin = os.Stdin
	cmd.Run()
}

func getTermSize() (int, int) {
	cmd := exec.Command("stty", "size")
	cmd.Stdin = os.Stdin
	out, err := cmd.Output()
	if err != nil {
		return 24, 80
	}
	parts := strings.Fields(string(out))
	if len(parts) != 2 {
		return 24, 80
	}
	rows, _ := strconv.Atoi(parts[0])
	cols, _ := strconv.Atoi(parts[1])
	return rows, cols
}

func drawScreen(lines []string, offset, rows, cols int, fileName string) {
	// Clear screen
	fmt.Print("\x1b[H\x1b[2J")

	for i := 0; i < rows-1; i++ {
		lineIdx := offset + i
		if lineIdx < len(lines) {
			line := lines[lineIdx]
			if len(line) > cols {
				line = line[:cols]
			}
			fmt.Printf("%s\r\n", line)
		} else {
			fmt.Print("~\r\n")
		}
	}

	// Status bar
	status := fmt.Sprintf("%s: (%d/%d)", fileName, offset+1, len(lines))
	if len(status) > cols {
		status = status[:cols]
	}
	fmt.Printf("\x1b[7m%s\x1b[m", status)
}

func readKey() string {
	var buf [16]byte
	n, err := os.Stdin.Read(buf[:])
	if err != nil {
		return ""
	}
	return string(buf[:n])
}
EOF
