{"command":"cat <<'EOF' > oviewer/draw.go
package oviewer

import (
	"fmt"
	"strings"
)

func (r *Root) Draw() {
	rows, cols := r.Term.GetSize()
	fmt.Print("\x1b[H") // Move to 1,1

	headerRows := r.Header
	if headerRows > len(r.Doc.Lines) {
		headerRows = len(r.Doc.Lines)
	}

	// Draw headers
	for i := 0; i < headerRows; i++ {
		r.drawLine(i, cols)
	}

	// Draw body
	bodyRows := rows - headerRows - 1
	for i := 0; i < bodyRows; i++ {
		lineIdx := r.Offset + headerRows + i
		if lineIdx < len(r.Doc.Lines) {
			r.drawLine(lineIdx, cols)
		} else {
			fmt.Print("~\x1b[K\r\n")
		}
	}

	// Draw status bar
	r.drawStatus(rows, cols)
}

func (r *Root) drawLine(idx int, cols int) {
	line := r.Doc.Lines[idx]
	// Handle line numbering
	if r.LineNumMode {
		num := fmt.Sprintf("%d ", idx+1)
		fmt.Printf("\x1b[33m%s\x1b[m", num)
		cols -= len(num)
	}
	if len(line) > cols {
		line = line[:cols]
	}
	fmt.Printf("%s\x1b[K\r\n", line)
